// PostgREST returns an array. Depending on the n8n build that arrives either as
// one item holding that array, or as one item per row - so normalise both
// rather than betting on one. Betting on [0] silently yields undefined on the
// other shape, and downstream that reads as "this row does not exist", which
// denies a perfectly valid user with a 402.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.id) return it;
  }
  return null;
}

const profile = firstRow('Get Profile Row') || {};
const active = profile.subscription_status === 'active';

// Most recent monthly anniversary of the subscription start, anchored to the
// original date rather than stepped month by month, so it cannot drift.
// Counting calendar months instead would hand someone who subscribed on the
// 20th a fresh allowance eleven days later.
function periodStart(startedAt){
  if (!startedAt) return null;
  const start = new Date(startedAt);
  if (isNaN(start)) return null;
  const now = new Date();
  let months = (now.getFullYear() - start.getFullYear()) * 12 + (now.getMonth() - start.getMonth());
  if (now.getDate() < start.getDate()) months--;
  if (months < 0) months = 0;
  const d = new Date(start);
  d.setMonth(start.getMonth() + months);
  return d;
}

const ps = active ? periodStart(profile.subscription_started_at) : null;

// Epoch fallback keeps the follow-up query valid; the result is ignored when
// has_period is false.
return [{ json: { period_start: (ps || new Date(0)).toISOString(), has_period: !!ps } }];

// A lookup that missed now arrives as one EMPTY item rather than zero items,
// so the branch reaches here instead of stopping dead. Say so plainly - a
// render that cannot find its own row must fail loudly, not hang the app.
const _r = $('Get Render Row').first().json;
const _row = Array.isArray(_r) ? _r[0] : _r;
if (!_row || !_row.id) {
  return [{ json: { rows_exist: false, has_access: false, should_charge: false,
                    reason: 'render_row_not_found' } }];
}

// PostgREST returns an array. Depending on the n8n build that arrives either as
// one item holding that array, or as one item per row - so normalise both
// rather than betting on one. Betting on [0] silently yields undefined on the
// other shape, and downstream that reads as "this row does not exist", which
// denies a perfectly valid user with a 402.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.id) return it;
  }
  return null;
}

const body = $('Webhook').first().json.body;
const renderRow = firstRow('Get Render Row');
const profileRow = firstRow('Get Profile Row');
const FREE_CORRECTIONS = 2;

// Monthly render allowance per plan. Without this a $5 Starter account could
// render without limit. Studio is SOLD as unlimited, so its number is a safety
// ceiling against runaway image-gen spend rather than an advertised quota - a
// normal user never reaches it.
const PLAN_ALLOWANCE = { starter: 7, crew: 16, pro: 35, studio: 300 };
function allowanceFor(planName){
  const p = (planName || '').trim().toLowerCase();
  const key = Object.keys(PLAN_ALLOWANCE).find(k => p.includes(k));
  return key ? PLAN_ALLOWANCE[key] : null;
}

// The webhook is public and takes render_id and user_id as separate inputs.
// Without this check a caller could pass their own user_id alongside someone
// else's render_id and write to a stranger's render.
const rowsExist = !!renderRow && !!profileRow;
const ownsRender = rowsExist && renderRow.user_id === body.user_id;

const isCorrection = !!body.correction_prompt;
const subscriptionActive = rowsExist && profileRow.subscription_status === 'active';
const hasCredits = rowsExist && (profileRow.credits_balance || 0) >= 1;
const freeCorrection = isCorrection && rowsExist && (renderRow.corrections_used || 0) < FREE_CORRECTIONS;

// Usage this billing period. A correction reuses its original render row, so
// it never counts a second time against the allowance.
const period = $('Compute Period').first().json || {};
const used = $('Count Period Renders').all().map(i => i.json).filter(j => j && j.id).length;
const allowance = subscriptionActive ? allowanceFor(profileRow.subscription_plan) : null;

// Fail open on anything unknown - an unrecognised plan name or a missing
// period anchor must not lock a paying customer out.
const allowanceApplies = subscriptionActive && !!allowance && !!period.has_period && !isCorrection;
const withinAllowance = !allowanceApplies || used < allowance;
const overAllowance = allowanceApplies && !withinAllowance;

const allowed = ownsRender && (
  (subscriptionActive && withinAllowance) || hasCredits || freeCorrection
);

// Decided once here so the charge and the refund can never disagree.
const shouldCharge = allowed && !subscriptionActive && (!isCorrection || !freeCorrection);

return [{
  json: {
    allowed,
    should_charge: shouldCharge,
    owns_render: ownsRender,
    rows_exist: rowsExist,
    is_correction: isCorrection,
    free_correction: freeCorrection,
    subscription_active: subscriptionActive,
    over_allowance: overAllowance,
    period_used: used,
    period_allowance: allowance
  }
}];

// PostgREST returns an array, and this n8n build splits it into one item per
// row - so .first().json IS the row, and [0] on it is undefined. Confirmed
// against execution 1416, which died here reading original_photo_url off
// undefined. Normalise both shapes rather than betting on either.
function firstRow(nodeName){
  let items = [];
  try { items = $(nodeName).all().map(i => i.json).filter(Boolean); } catch (e) { return null; }
  for (const it of items){
    if (Array.isArray(it)){ if (it[0]) return it[0]; continue; }
    if (it && it.id) return it;
  }
  return null;
}

const body = $('Webhook').first().json.body;
const renderRow = firstRow('Get Render Row') || {};
const profileRow = firstRow('Get Profile Row') || {};
const access = $('Compute Access').first().json;

const isCorrection = access.is_correction;
const targetHex = isCorrection ? renderRow.color_hex : (body.color_hex || renderRow.color_hex || null);

// What the user typed in the app's "Paint the" box.
const surface = (body.surface || '').trim() || 'surface';

// Up to three picks, named explicitly so the model uses these exact colours.
const colors = Array.isArray(body.colors) ? body.colors : [];
const colorList = colors.length
  ? colors.map(c => `${c.name} (${c.hex})`).join(', ')
  : (renderRow.color_name || body.color_name || '');

let basePrompt;
if (targetHex || colorList) {
  basePrompt = `Repaint the ${surface}. Use these exact colours: ${colorList || targetHex}. Keep everything else in the photo identical - same lighting, same room geometry, same hardware, same materials elsewhere.`;
} else {
  basePrompt = `Repaint the ${surface}: ${body.prompt || renderRow.prompt}. Keep everything else in the photo identical - same lighting, same room geometry, same hardware.`;
}

const correctionSuffix = isCorrection ? ` Adjustment requested: "${body.correction_prompt}".` : '';

// Corrections re-render from the UNBRANDED copy. Feeding the branded one back
// in would composite the logo a second time, and again on every correction.
const initImageUrl = (isCorrection && renderRow.rendered_photo_url)
  ? renderRow.rendered_photo_url
  : renderRow.original_photo_url;

return [{
  json: {
    render_id: renderRow.id,
    user_id: renderRow.user_id,
    is_correction: isCorrection,
    free_correction: access.free_correction,
    subscription_active: access.subscription_active,
    target_hex: targetHex,
    colors,
    surface,
    init_image_url: initImageUrl,
    render_prompt: basePrompt + correctionSuffix,
    corrections_used: renderRow.corrections_used || 0,
    brand_logo_url: body.brand_logo_url || profileRow.brand_logo_url,
    brand_contact: body.brand_contact || profileRow.brand_contact
  }
}];

// Two renders, one seed.
//
// The first is the picture. The second is a stencil: the same photo with the
// cabinets in a colour no kitchen contains, rendered only so the colour pass
// knows exactly which pixels are the surface. Masking on the real paint colour
// cannot do that job - Urbane Bronze sits at chroma 4.1 and is
// indistinguishable from half a warm kitchen, which came back as grey walls
// and speckled countertops twice.
//
// They share a seed because a mask taken from one render is only valid on the
// other if the two agree about where the cabinets are. Measured on a
// seed-locked pair, the flag mask splits the real render into mean L 22.3
// inside and 66.6 outside.
const build = $('Build Prompt').first().json;
const flag = $('Pick Flag Colour').first().json;
if (!flag || flag.ok !== true || !flag.flagHex) {
  throw new Error('flag picker: ' + ((flag && flag.reason) || 'no response'));
}

// Binary is stored in filesystem mode here, so `binary.original.data` is a
// REFERENCE, not base64. The helper resolves it to real bytes.
const img = await this.helpers.getBinaryDataBuffer(0, 'original');

// Kontext ignores the source shape and answers at its own default - it handed
// back 1024x1024 for a 1244x1265 photo - so the aspect ratio has to be asked
// for explicitly. The parameter is real but fussy: "4:3" is honoured,
// "983:1000" is silently ignored. Snap to a known-good ratio rather than
// computing an exact one.
function dimensions(buf) {
  // PNG: IHDR carries width and height as big-endian uint32 at bytes 16 and 20.
  if (buf.length > 24 && buf[0] === 0x89 && buf[1] === 0x50) {
    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
  }
  // JPEG: walk the marker chain to a start-of-frame and read its dimensions.
  if (buf.length > 4 && buf[0] === 0xFF && buf[1] === 0xD8) {
    let i = 2;
    while (i < buf.length - 9) {
      if (buf[i] !== 0xFF) { i++; continue; }
      const m = buf[i + 1];
      // SOF0-SOF15 carry the size; C4, C8 and CC are other markers in range.
      if (m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) {
        return { h: buf.readUInt16BE(i + 5), w: buf.readUInt16BE(i + 7) };
      }
      i += 2 + buf.readUInt16BE(i + 2);
    }
  }
  return null;
}

const RATIOS = [
  ['1:1', 1], ['4:3', 4 / 3], ['3:4', 3 / 4], ['3:2', 3 / 2], ['2:3', 2 / 3],
  ['16:9', 16 / 9], ['9:16', 9 / 16], ['5:4', 5 / 4], ['4:5', 4 / 5],
  ['7:5', 7 / 5], ['5:7', 5 / 7], ['2:1', 2], ['1:2', 1 / 2],
];

const dim = dimensions(img);
let aspect = null;
if (dim && dim.w && dim.h) {
  const want = dim.w / dim.h;
  let best = null;
  for (const [name, r] of RATIOS) {
    // Compare in log space so 2:1 and 1:2 are judged as equally far out.
    const err = Math.abs(Math.log(r / want));
    if (!best || err < best.err) best = { name, err };
  }
  aspect = best.name;
}

// Derived from the render id rather than random, so re-running a render that
// went wrong reproduces it exactly instead of rolling a new scene.
let seed = 0;
for (const ch of String(build.render_id || 'paintrz')) {
  seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
}
seed = seed % 2147483647;

const base = {
  input_image: img.toString('base64'),
  output_format: 'jpeg',
  // 2 is the highest BFL accepts once an input image is present.
  safety_tolerance: 2,
  // Upsampling rewrites the instruction, which would let the model
  // reinterpret the colour names - exactly what the LAB pass exists to pin
  // down - and would break the two prompts apart from each other.
  prompt_upsampling: false,
  seed
};
if (aspect) base.aspect_ratio = aspect;

// Same sentence, same seed, one word different. The closer these two prompts
// are, the better the two renders agree about where the cabinets are.
const flagPrompt = 'Repaint the ' + build.surface + ' in flat pure ' + flag.flagName +
  ', hex ' + flag.flagHex + ', fully saturated, like a solid colour mask. ' +
  'Paint every part of the ' + build.surface + ' this exact colour. ' +
  'Keep everything else in the photo completely unchanged - same walls, same floor, ' +
  'same countertops, same appliances, same lighting.';

return [
  { json: { ...base, prompt: build.render_prompt }, pairedItem: 0 },
  { json: { ...base, prompt: flagPrompt }, pairedItem: 0 }
];

// Two renders are in flight, so this gate is all-or-nothing: the branch only
// moves on once BOTH are Ready, and otherwise hands the submit records back to
// the Wait node to poll again.
//
// Which render is which is read from the prompt BFL echoes back in
// result.prompt, not from item order. Order does survive an n8n loop today,
// but nothing enforces it, and getting this backwards would mask the picture
// with itself and hand the customer a magenta kitchen.
const flagHex = $('Pick Flag Colour').first().json.flagHex;

// $runIndex counts this node's own runs inside the execution, which is what
// lets the cap survive the loop back to Wait - a counter carried in the item
// would reset. 40 x 3s is about two minutes; Kontext Pro normally lands in
// thirty seconds.
const MAX_POLLS = 40;

const items = $input.all().map(i => i.json || {});
const PENDING = ['Pending', 'Queued', 'Processing', 'Request Accepted'];

for (const r of items) {
  const status = r.status || '';
  if (status === 'Ready') continue;
  // Anything outside this list is terminal - Error, Content Moderated,
  // Request Moderated, Task not found. Looping on those burns two minutes and
  // then reports a timeout, which hides the actual cause.
  if (PENDING.indexOf(status) === -1) {
    const detail = r.details ? ' - ' + JSON.stringify(r.details) : '';
    throw new Error('BFL returned status "' + status + '"' + detail);
  }
}

const ready = items.every(r => r.status === 'Ready');

if (!ready) {
  if ($runIndex + 1 >= MAX_POLLS) {
    throw new Error('BFL still working after ' + MAX_POLLS + ' polls');
  }
  // Back round with the polling records, not the poll responses.
  return $('Submit BFL Kontext').all().map((i, n) => ({ json: i.json, pairedItem: n }));
}

const out = items.map((r, n) => {
  const sample = r.result && (r.result.sample || r.result.url);
  if (!sample) throw new Error('BFL reported Ready with no result.sample');
  const echoed = (r.result && r.result.prompt) || '';
  return {
    json: {
      ready: true,
      is_flag: echoed.indexOf(flagHex) !== -1,
      sample_url: sample,
      seed: r.result && r.result.seed,
      polls: $runIndex + 1
    },
    pairedItem: n
  };
});

if (out.filter(o => o.json.is_flag).length !== 1) {
  throw new Error('expected exactly one flag render, got ' + out.filter(o => o.json.is_flag).length);
}

return out;

// Both renders arrive here: the picture, and the stencil. Neither becomes an
// n8n binary - BFL hands back signed delivery URLs and the image service
// fetches them itself. Those URLs are short-lived, so nothing may sit between
// here and that fetch.
const build = $('Build Prompt').first().json;
const flag = $('Pick Flag Colour').first().json;

const items = $input.all().map(i => i.json);
const stencil = items.find(i => i.is_flag);
const picture = items.find(i => !i.is_flag);
if (!stencil || !picture) {
  throw new Error('expected one flag render and one real render, got ' + items.length);
}

// The original is already a public Supabase URL, so the service fetches it
// rather than round-tripping several MB of base64 through n8n. On a correction
// this is the previous UNBRANDED render, which is what corrections build on.
const originalUrl = build.init_image_url;

const primary = Array.isArray(build.colors) && build.colors.length ? build.colors[0] : null;

return [{ json: {
  render_id: build.render_id,
  original_url: originalUrl,
  rendered_url: picture.sample_url,
  // The stencil, and the threshold the picker measured against THIS photo
  // rather than a constant - a room already holding some of the flag's hue
  // needs a higher bar.
  flag_url: stencil.sample_url,
  flag_hex: flag.flagHex,
  flag_threshold: flag.threshold,
  target_hex: build.target_hex,
  // LRV is the manufacturer's published lightness and a better target than the
  // hex, which is only a screen approximation of the chip. The colour proxy
  // returns it, and app.html forwards it on the colours it resolves.
  target_lrv: (primary && primary.lrv != null) ? primary.lrv : null,
  brand_logo_url: build.brand_logo_url || null,
  brand_contact: build.brand_contact || null
}, pairedItem: 0 }];

// The service answers with JSON even when it fails, so a failure arrives here
// as ok:false rather than as a dead branch. Throwing turns it into the error
// output, which routes to Mark Failed and refunds the credit.
const r = $input.first().json;
if (!r || r.ok !== true) {
  throw new Error('image service: ' + ((r && r.reason) || 'no response'));
}

const build = $('Build Prompt').first().json;

// Two items -> the upload node runs twice, once per variant, exactly as the
// old Code node did. stats rides along on the clean variant so the execution
// log records what the colour pass actually decided.
return [
  {
    json: { render_id: build.render_id, variant: 'render', stats: r.stats, ms: r.ms,
            bfl_cost: $('Submit BFL Kontext').first().json.cost },
    binary: { data: { data: r.render_b64, mimeType: 'image/jpeg', fileName: 'render.jpg' } },
    pairedItem: 0
  },
  {
    json: { render_id: build.render_id, variant: 'branded' },
    binary: { data: { data: r.branded_b64, mimeType: 'image/jpeg', fileName: 'branded.jpg' } },
    pairedItem: 0
  }
];
